import{z as i,x as n,o as s,c as A,q as t,j as r,D as E,d as l,s as o,S as p,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"光源相干性与 speckle","description":"","frontmatter":{"title":"光源相干性与 speckle","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/speckle.md","filePath":"litho/speckle.md","lastUpdated":1791063341000}'),d={name:"litho/speckle.md"};function c(h,e,m,k,C,D){const B=n("Mermaid");return s(),A("div",null,[e[2]||(e[2]=t('<h1 id="光源相干性与-speckle" tabindex="-1">光源相干性与 speckle <a class="header-anchor" href="#光源相干性与-speckle" aria-label="Permalink to &quot;光源相干性与 speckle&quot;">​</a></h1><div class="epigraph"><p>相干光打在随机相位屏上，像面出现固定颗粒；积分足够多的不相干通道，颗粒才被平均掉。</p><footer>—— Goodman, Speckle Phenomena in Optics；互相干接口见 Born &amp; Wolf</footer></div><p><a href="/litho/temporal-spatial-coherence">上一课</a>把时间轴与空间轴拆开。缺口是：若空间相干过长、时间积分又不够，空中像会带<strong>斑纹（speckle）</strong>——不是 OPC 没修到的禁戒节距，而是相干叠加的随机干涉图。本课钉光刻为什么必须把 speckle 洗掉。标量骨架在高 NA 何时失效，留给<a href="/litho/scalar-breakdown-high-na">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想计算里掩模是确定的 \\(t(\\mathbf{x})\\)，像是确定的 \\(I\\)。真实照明若接近单模、波前碰到粗糙面、多层膜或气体扰动，像面场是随机相幅叠加，强度呈负指数统计，对比接近 1 的颗粒，横向尺度约等于 PSF 宽度。这就是 speckle。</p><p><span class="marginnote">直觉类比：激光笔照在毛玻璃墙上出现的那种麻点就是 speckle——激光太「纯」（相干性高），毛玻璃各处随机相位让散射光彼此干涉，结成固定的亮暗颗粒；普通手电各点互不相干，照出来就是均匀光斑。</span></p><p>缺口不是再定义横向相干长度，而是：投影光刻的空中像若带着颗粒，阈值轮廓会随颗粒抖动，CD 与孔出现随机缺失的假象——和 EUV 光子泊松不是同一机制，却同样吃良率。准分子激光被设计成许多纵模、照明被设计成填充 \\(S\\)，正是为了让 SOCS 通道数足够、时间上平均足够。</p><h3 id="静态斑与扫描平均" tabindex="-1">静态斑与扫描平均 <a class="header-anchor" href="#静态斑与扫描平均" aria-label="Permalink to &quot;静态斑与扫描平均&quot;">​</a></h3><p>若随机屏相对曝光静止、光源又太相干，颗粒在整段曝光里固定，剂量积分帮不上忙。扫描狭缝的时间平均只沿扫描向糊一次，糊不掉垂直扫描向的颗粒。必须在<strong>照明侧</strong>降低空间相干（扩展源、匀光、衍射光学元件打散），或在时间侧用足够多独立实现（脉冲间互不相干）。EUV 等离子体脉冲之间空间模式也在变，对 speckle 是有利的；不要把它和剂量稳定性混成一个「源质量」分数。</p><p><span class="marginnote">显微镜激光照明、干涉光刻、某些检验工具会故意保留高相干，于是 speckle 必须另管。扫描仪投影成像默认要的是平滑空中像。本课对象是后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>判据：相干体积里独立单元数 \\(N\\)。空间上 \\(N_s\\sim\\) 源填充的分辨率元；时间上 \\(N_t\\sim\\) 曝光时间内互不相干脉冲（或相干时间去除以曝光时间）。强度涨落相对均值约 \\(1/\\sqrt{N_s N_t}\\)。工程上把 \\(S\\) 做大、脉冲做多，直到颗粒对比远小于工艺对比预算。</p><p><span class="marginnote">数字实例：涨落对比约 \\(1/\\sqrt{N}\\)。空间与时间合计 \\(N=400\\) 个独立通道时，对比约 \\(1/20=5\\%\\)；要压到 1%，\\(N\\) 要上万。这就是「扩展源、多脉冲」两句口号背后的算术。</span></p><p>计算上：TCC 已经假定源点互不相干并把强度相加——这正是对 speckle 的系综平均。若模拟只用单源点相干成像去代表整场，会人为造出不存在的条纹与颗粒。Abbe 法源点过疏，也会留下假纹理，看起来像 speckle，其实是求积误差。</p><p><span class="marginnote">常见误区：仿真里只放一个源点做相干成像去代表整场，图上会凭空长出条纹和颗粒——那是平均没做够的假象，不是工艺真会印出 speckle。</span></p>',15)),(s(),r(p,null,{default:E(()=>[o(B,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIGH%5B%22%E7%A9%BA%E9%97%B4%E7%9B%B8%E5%B9%B2%E8%BF%87%E9%95%BF%22%5D%20--%3E%20SP%5B%22%E5%83%8F%E9%9D%A2%20speckle%22%5D%0A%20%20FEW%5B%22%E7%8B%AC%E7%AB%8B%E8%84%89%E5%86%B2%E8%BF%87%E5%B0%91%22%5D%20--%3E%20SP%0A%20%20FILL%5B%22%E6%89%A9%E5%B1%95%20S%20%2F%20%E5%8C%80%E5%85%89%22%5D%20--%3E%20AVG%5B%22%E5%BC%BA%E5%BA%A6%E7%B3%BB%E7%BB%BC%E5%B9%B3%E5%9D%87%22%5D%0A%20%20PUL%5B%22%E5%A4%9A%E8%84%89%E5%86%B2%E4%B8%8D%E7%9B%B8%E5%B9%B2%22%5D%20--%3E%20AVG%0A%20%20AVG%20--%3E%20SMOOTH%5B%22%E5%B9%B3%E6%BB%91%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h3",{id:"与随机性课的边界",tabindex:"-1"},[l("与随机性课的边界 "),a("a",{class:"header-anchor",href:"#与随机性课的边界","aria-label":'Permalink to "与随机性课的边界"'},"​")],-1)),e[4]||(e[4]=a("p",null,"EUV 缺孔、LER 的泊松与化学随机，是光子与分子计数；speckle 是经典相干场的随机干涉。胶不能「平均掉」已经写进剂量图的颗粒，除非再加一层空间模糊——那是在付 NILS 的账。不要把 speckle 写进 RLS 三角里当第四个字母。",-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"随机相位使 PSF 旁瓣之间的干涉从相长跳到相消，亮暗斑的特征尺寸跟核走，故颗粒「看起来像分辨率」。降低空间相干等于让许多独立核的强度叠上，对比按 \\(1/\\sqrt{N}\\) 掉。这与部分相干降低密栅对比不是同一句话：后者是确定 TCC 对确定物体的调制下降；前者是同一物体上叠加随机纹理。",-1)),(s(),r(p,null,{default:E(()=>[o(B,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%9A%8F%E6%9C%BA%E7%9B%B8%E4%BD%8D%E5%B1%8F%22%5D%20--%3E%20G%5B%22%E7%9B%B8%E5%B9%B2%E5%8F%A0%E5%8A%A0%EF%BC%9A%E9%A2%97%E7%B2%92%E5%AF%B9%E6%AF%94%E6%8E%A5%E8%BF%91%201%22%5D%0A%20%20NS%5B%22%E7%A9%BA%E9%97%B4%E9%80%9A%E9%81%93%20Ns%EF%BC%9A%E6%89%A9%E5%B1%95%E6%BA%90%20%2F%20%E5%8C%80%E5%85%89%22%5D%20--%3E%20N%7B%22%E7%8B%AC%E7%AB%8B%E9%80%9A%E9%81%93%E6%95%B0%20Ns%20%C3%97%20Nt%20%E5%A4%9F%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20NT%5B%22%E6%97%B6%E9%97%B4%E9%80%9A%E9%81%93%20Nt%EF%BC%9A%E4%BA%92%E4%B8%8D%E7%9B%B8%E5%B9%B2%E8%84%89%E5%86%B2%22%5D%20--%3E%20N%0A%20%20N%20--%3E%7C%22%E5%A4%9F%22%7C%20OK%5B%22%E5%AF%B9%E6%AF%94%20~%201%2F%E2%88%9AN%EF%BC%8C%E7%A9%BA%E4%B8%AD%E5%83%8F%E5%B9%B3%E6%BB%91%22%5D%0A%20%20N%20--%3E%7C%22%E4%B8%8D%E5%A4%9F%22%7C%20BAD%5B%22%E9%98%88%E5%80%BC%E8%BD%AE%E5%BB%93%E6%8A%96%EF%BC%9ACD%20%E9%9A%8F%E6%9C%BA%E5%81%8F%E5%B7%AE%20%2F%20%E5%81%87%E7%BC%BA%E5%AD%94%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p>薄膜界面若有粗糙，也可以做相位屏。DUV 浸没气泡、水印是缺陷，不是经典 speckle 统计；EUV 多层粗糙既贡献散射晕光，也可贡献斑，主干 flare 课管晕光，本课只保留「相干随机干涉」这一条。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Goodman 的完全相干 speckle 统计（负指数、对比 1）是极限。部分相干、偏振分集、有限积分都会降低对比。禁止编造某台 EUV 的「speckle 纳米表」。也不要把像素化 SMO 的确定衍射图叫成 speckle。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>speckle 是高空间相干加随机相位的颗粒，尺度约 PSF。</li><li>扩展源与多脉冲独立实现把它平均掉；TCC 默认已经做了源点平均。</li><li>与光子泊松、与确定的禁戒节距都不是同一机制。</li><li>单源点模拟会伪造颗粒。</li><li>下一课：标量卷积骨架在高 NA 的失效。</li><li>出处：Goodman, <em>Speckle Phenomena in Optics</em>；Born &amp; Wolf。</li></ul>',5))])}const N=i(d,[["render",c]]);export{f as __pageData,N as default};
